"// Input: { entry_id: string }. Read-only RCSB GraphQL and Crossref public APIs.
// RCSB's explicitly designated primary citation establishes association; Crossref
// confirms the DOI is a journal article and supplies exact title array/publisher.
const entry_id = String(input?.entry_id || '').trim().toUpperCase();
if (!/^[A-Z0-9]+$/.test(entry_id)) throw new Error('A valid entry_id is required');
async function get(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return r.json();
}
const query = 'query($id:String!){entry(entry_id:$id){rcsb_id rcsb_primary_citation{id title pdbx_database_id_DOI year}}}';
const u = new URL('https://data.rcsb.org/graphql');
u.searchParams.set('query', query);
u.searchParams.set('variables', JSON.stringify({id:entry_id}));
const graph = await get(u.toString());
if (graph.errors) throw new Error(JSON.stringify(graph.errors));
const entry = graph.data?.entry;
const citation = entry?.rcsb_primary_citation;
const doi = citation?.pdbx_database_id_DOI;
if (entry?.rcsb_id !== entry_id || citation?.id !== 'primary' || !doi) throw new Error('Primary citation DOI could not be established');
const work = (await get('https://api.crossref.org/works/' + encodeURIComponent(doi))).message;
const normalize = s => String(s).normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
if (work?.DOI?.toLowerCase() !== doi.toLowerCase() || work.type !== 'journal-article') throw new Error('DOI is not a verified journal article');
if (!Array.isArray(work.title) || !work.title.length || !work.title.some(t=>normalize(t)===normalize(citation.title))) throw new Error('Publication titles disagree');
if (!work.publisher) throw new Error('Publisher unavailable');
return {entry_id,doi:work.DOI,title:work.title,publisher:work.publisher};
"

